-- ============================================
-- SEED — cours de seconde (programme 2026)
-- À coller dans : Supabase > SQL Editor > New query
-- ============================================
-- Contenu vérifié contre le texte officiel du programme de seconde
-- générale et technologique 2026 (vecteurs : ancien programme repris à
-- zéro pour la génération d'Anaïs ; valeur absolue limitée à la distance
-- et à |x - a| <= r ; fonctions de référence = valeur absolue, carré,
-- inverse). Chaque "contenu" est le JSON des blocs tel que l'éditeur de
-- cours (CoursEditor.jsx) les attend : [{id, type, content, titre?}].
-- Lancez ce script une seule fois : relancer créerait des doublons
-- (pas de contrainte d'unicité sur (niveau, chapitre)).

INSERT INTO cours (titre, matiere, niveau, chapitre, contenu, publie) VALUES
('Intervalles et ensembles de nombres', 'Mathématiques', '2nde', 'Intervalles et ensembles de nombres', $coursJson1$[{"id": 1, "type": "texte", "content": "Si on te dit « prends un nombre entre 2 et 5 », tu ne sais pas lequel — mais tu sais où chercher. Un intervalle, c'est exactement cette zone de recherche, écrite proprement."}, {"id": 2, "type": "definition", "content": "Chaque ensemble contient le précédent, comme des poupées russes imbriquées :\nℕ (entiers naturels : 0, 1, 2, 57…) est dans ℤ (entiers relatifs : −3, 0, 8…),\nqui est dans 𝔻 (décimaux : 0,25 ; −3,7…),\nqui est dans ℚ (fractions : 1/3 ; −7/4…),\nqui est dans ℝ (tous les nombres de la droite, irrationnels compris : √2, π).\n1/3 est rationnel mais pas décimal. √2 et π sont réels sans être rationnels — on dit irrationnels.", "titre": "Les ensembles de nombres, comme des poupées russes"}, {"id": 3, "type": "definition", "content": "2 ≤ x ≤ 5  →  [2 ; 5]  (2 et 5 inclus)\n2 < x < 5  →  ]2 ; 5[  (2 et 5 exclus)\n2 ≤ x < 5  →  [2 ; 5[  (2 inclus, 5 exclu)\nx ≥ 2  →  [2 ; +∞[  (tout à partir de 2)\nx < 5  →  ]−∞ ; 5[  (tout avant 5)", "titre": "Les intervalles : 5 formes à connaître"}, {"id": 4, "type": "remarque", "content": "Le crochet « mord » vers le nombre qu'il inclut, et s'ouvre vers l'extérieur pour celui qu'il exclut. ∞ n'est jamais atteint, donc toujours un crochet ouvert de son côté. On écrit x ∈ [2 ; 5] pour « x appartient à [2 ; 5] ».", "titre": "La règle du crochet"}, {"id": 5, "type": "definition", "content": "Intersection ∩ : les nombres qui sont dans les deux intervalles en même temps — c'est un « et ».\nRéunion ∪ : les nombres qui sont dans l'un ou dans l'autre — c'est un « ou ».", "titre": "Réunion et intersection : « ou » et « et »"}, {"id": 6, "type": "exemple", "content": "Place les deux intervalles sur la même droite, l'un sous l'autre, et regarde où ils se chevauchent (intersection) ou ce qu'ils couvrent à eux deux (réunion).\n[1 ; 5] ∩ [3 ; 8] = [3 ; 5]\n[1 ; 3] ∪ [2 ; 6] = [1 ; 6]\n]−∞ ; 2[ ∪ [2 ; +∞[ = ℝ\n]−∞ ; 2[ ∩ [2 ; +∞[ = ∅  (2 est dans le deuxième, pas dans le premier : aucun point commun)", "titre": "Le réflexe qui évite les erreurs : dessiner"}, {"id": 7, "type": "remarque", "content": "Oublier le sens du crochet : ]2 ; 5] et [2 ; 5] ne sont pas le même ensemble.\nÉcrire [2 ; 5] ∩ [7 ; 9] = [5 ; 7] : en réalité il n'y a aucun point commun, c'est ∅.\nPour une égalité comme x = 3 ou x = 5, on ne met pas d'intervalle : on liste les deux valeurs, {3 ; 5}.", "titre": "Pièges classiques"}, {"id": 8, "type": "remarque", "content": "Les exercices progressifs de ce chapitre sont dans l'onglet Exercices — vas-y une fois le cours relu, ça se joue en quelques minutes.", "titre": "Pour aller plus loin"}]$coursJson1$, true),

('Valeur absolue et distance', 'Mathématiques', '2nde', 'Valeur absolue et distance', $coursJson2$[{"id": 1, "type": "texte", "content": "La valeur absolue d'un nombre, c'est sa distance à zéro — on efface juste le signe. |5| = 5 et |−5| = 5 : les deux sont à 5 pas de zéro, dans des directions opposées."}, {"id": 2, "type": "formule", "content": "|x| = \\begin{cases} x & \\text{si } x \\geq 0 \\\\ -x & \\text{si } x \\leq 0 \\end{cases}"}, {"id": 3, "type": "exemple", "content": "|5| = 5, |−3| = 3, |0| = 0. Une valeur absolue n'est jamais négative — une distance ne peut pas l'être."}, {"id": 4, "type": "definition", "content": "Sur la droite graduée, la distance entre a et b est la valeur absolue de leur différence. C'est la clé de tout le chapitre : dès que tu vois |x − a|, lis-le comme « la distance de x au point a ».", "titre": "La vraie idée : une distance entre deux nombres"}, {"id": 5, "type": "formule", "content": "d(a ; b) = |a - b| = |b - a|"}, {"id": 6, "type": "exemple", "content": "La distance entre −2 et 5 vaut |−2 − 5| = |−7| = 7."}, {"id": 7, "type": "methode", "content": "|x − a| = r  →  x = a − r ou x = a + r  (les deux points à distance r de a)\n|x − a| ≤ r  →  x ∈ [a − r ; a + r]  (les points à distance au plus r de a)\nLes versions strictes (< et >) suivent la même logique, avec des crochets ouverts.", "titre": "Résoudre avec une valeur absolue (r positif)"}, {"id": 8, "type": "remarque", "content": "Attention : le programme officiel de seconde ne demande que la distance entre deux nombres et le cas |x − a| ≤ r (intervalle centré en a). Les cas égalité et ≥ sont de bons entraînements, mais pas exigibles au contrôle."}, {"id": 9, "type": "exemple", "content": "|x − 3| = 2 : à distance 2 de 3. x = 1 ou x = 5.\n|x − 3| ≤ 2 : à distance au plus 2 de 3. x ∈ [1 ; 5].\n|x + 1| < 3 : on relit x + 1 comme x − (−1), le centre est −1. x ∈ ]−4 ; 2[.\n|x| = −2 : impossible, une valeur absolue n'est jamais négative. Aucune solution.", "titre": "Exemples résolus"}, {"id": 10, "type": "remarque", "content": "Pour |x + 1|, le centre est −1, pas +1 : il faut relire x + 1 en x − (−1).\n|a + b| n'est pas égal à |a| + |b| en général : |3 + (−5)| = 2, mais |3| + |−5| = 8.\nUne distance est toujours positive : jamais de résultat négatif.", "titre": "Pièges classiques"}, {"id": 11, "type": "remarque", "content": "Les exercices progressifs de ce chapitre sont dans l'onglet Exercices.", "titre": "Pour aller plus loin"}]$coursJson2$, true),

('Inéquations du premier degré', 'Mathématiques', '2nde', 'Inéquations du premier degré', $coursJson3$[{"id": 1, "type": "texte", "content": "Résoudre une inéquation, c'est trouver tous les nombres x qui la rendent vraie — pas un seul nombre, mais toute une zone. La réponse est donc un intervalle, jamais un nombre tout seul."}, {"id": 2, "type": "theoreme", "content": "On peut ajouter ou soustraire le même nombre des deux côtés : le sens ne change pas.\nOn peut multiplier ou diviser par un nombre positif : le sens ne change pas.\nMultiplier ou diviser par un nombre négatif inverse le sens de l'inégalité.", "titre": "Les trois règles"}, {"id": 3, "type": "remarque", "content": "Pourquoi cette troisième règle ? 2 < 5, mais en multipliant par −1 on obtient −2 > −5 : les nombres se rangent dans l'ordre inverse une fois qu'on change leur signe."}, {"id": 4, "type": "methode", "content": "1. Développer s'il y a des parenthèses (attention au signe moins devant).\n2. Regrouper les x d'un côté, les nombres de l'autre, en changeant les signes de ce qu'on déplace.\n3. Diviser par le coefficient de x — en inversant le sens s'il est négatif.\n4. Écrire la solution sous forme d'intervalle.", "titre": "La méthode, dans l'ordre"}, {"id": 5, "type": "exemple", "content": "3x − 5 ≤ 7 : 3x ≤ 12, donc x ≤ 4. Solution : ]−∞ ; 4].\n−2x + 1 > 7 : −2x > 6, on divise par −2 donc on inverse : x < −3. Solution : ]−∞ ; −3[.\n2x + 1 ≥ 5x − 8 : −3x ≥ −9, on divise par −3 : x ≤ 3. Solution : ]−∞ ; 3].\nDouble inégalité −3 < 2x + 1 ≤ 7 : on retire 1 partout, −4 < 2x ≤ 6, puis on divise par 2 : −2 < x ≤ 3.", "titre": "Exemples résolus"}, {"id": 6, "type": "methode", "content": "Pour 2x + 1 ≥ 5x − 8, teste x = 0 (dans la solution ]−∞ ; 3]) : 1 ≥ −8, vrai. Teste x = 4 (hors solution) : 9 ≥ 12, faux. Les deux tests concordent : la solution est cohérente.", "titre": "Le réflexe pour vérifier : une valeur test"}, {"id": 7, "type": "remarque", "content": "Oublier d'inverser le sens en divisant par un négatif — c'est l'erreur n°1.\nSe tromper de crochet : ≤ et ≥ donnent un crochet fermé, < et > un crochet ouvert.\nÉcrire la solution sous la forme x = 4 : une inéquation a tout un ensemble de solutions, pas une seule valeur.", "titre": "Pièges classiques"}, {"id": 8, "type": "remarque", "content": "Les exercices progressifs de ce chapitre sont dans l'onglet Exercices.", "titre": "Pour aller plus loin"}]$coursJson3$, true),

('Vecteurs : l''essentiel', 'Mathématiques', '2nde', 'Vecteurs dans le plan', $coursJson4$[{"id": 1, "type": "texte", "content": "Un vecteur, c'est juste un trajet. Tu pars d'un point, tu arrives à un autre, et trois choses comptent : la direction (quelle route), le sens (vers où sur cette route) et la longueur (combien de distance). $\\overrightarrow{AB}$ veut dire « le trajet de A vers B ». Rien de plus compliqué que ça pour commencer — tout le reste de ce cours en découle."}, {"id": 2, "type": "definition", "content": "Imagine deux voitures qui font exactement le même trajet — même route, même direction, même distance — mais parties de deux endroits différents. On dit que ce sont les mêmes vecteurs. Peu importe où on les dessine : seuls comptent direction, sens et longueur.", "titre": "Deux vecteurs identiques"}, {"id": 3, "type": "definition", "content": "Faire une translation de vecteur u, c'est faire glisser toute une figure d'un seul coup, dans la même direction, le même sens, la même distance pour chaque point. Si A devient A', alors $\\overrightarrow{AA'}$ = $\\vec{u}$ : c'est la définition même de « glisser selon u ».", "titre": "La translation, c'est glisser"}, {"id": 4, "type": "theoreme", "content": "ABCD est un parallélogramme exactement quand $\\overrightarrow{AB}$ = $\\overrightarrow{DC}$ — le trajet de A vers B est le même que celui de D vers C. C'est logique : si les deux côtés opposés sont « le même trajet », la figure ne peut être qu'un parallélogramme.", "titre": "Le parallélogramme, un raccourci pratique"}, {"id": 5, "type": "theoreme", "content": "Si tu vas de A à B, puis de B à C, au final tu es allé de A à C. C'est tout ce que dit Chasles : $\\overrightarrow{AB}$ + $\\overrightarrow{BC}$ = $\\overrightarrow{AC}$. Astuce pour ne pas se tromper : la lettre du milieu (B) doit être la même des deux côtés, et elle disparaît dans le résultat.", "titre": "Chasles : enchaîner deux trajets"}, {"id": 6, "type": "definition", "content": "« Direction, sens, longueur » décrits avec des mots, c'est flou. Pour être précis, on pose une grille avec deux directions de référence : i vers la droite, j vers le haut. Tout vecteur se décrit alors avec deux nombres : combien de pas selon i, combien de pas selon j. C'est exactement ce que tu faisais dans l'atelier en bougeant un point sur la grille et en lisant deux chiffres.", "titre": "Pourquoi un repère ?"}, {"id": 7, "type": "methode", "content": "$\\overrightarrow{AB}$ a pour coordonnées (x_B − x_A ; y_B − y_A) : toujours arrivée moins départ, dans cet ordre. Exemple : A(1 ; 2) et B(4 ; 6). On fait 4 − 1 = 3, puis 6 − 2 = 4. $\\overrightarrow{AB}$ a pour coordonnées (3 ; 4) : 3 pas à droite, 4 pas vers le haut.", "titre": "Les coordonnées de →AB"}, {"id": 8, "type": "methode", "content": "Une fois que chaque vecteur a deux nombres, additionner ou soustraire des vecteurs, c'est juste additionner ou soustraire ces nombres un par un : u(x ; y) et v(x′ ; y′) donnent u + v = (x + x′ ; y + y′) et u − v = (x − x′ ; y − y′). Multiplier un vecteur par un nombre k, c'est multiplier chaque coordonnée par k : k·u = (kx ; ky).", "titre": "Calculer avec les coordonnées"}, {"id": 9, "type": "definition", "content": "La norme d'un vecteur, notée ‖$\\overrightarrow{AB}$‖, c'est sa longueur réelle — pas le nombre de pas, la distance parcourue. Ça te rappelle quelque chose ? C'est Pythagore, caché : ‖$\\overrightarrow{AB}$‖ = $\\sqrt{x^2+y^2}$ où (x ; y) sont les coordonnées. Pour $\\overrightarrow{AB}$(3 ; 4) : $\\sqrt{3^2+4^2} = \\sqrt{25} = 5$.", "titre": "La norme : la vraie longueur du trajet"}, {"id": 10, "type": "definition", "content": "Le milieu d'un segment [AB], c'est la moyenne des coordonnées de A et de B — exactement comme une moyenne de notes. Milieu de [AB] = ((x_A + x_B)/2 ; (y_A + y_B)/2).", "titre": "Le milieu : pile au centre"}, {"id": 11, "type": "definition", "content": "Deux vecteurs sont colinéaires s'ils pointent dans la même direction — comme deux flèches parallèles, même si elles n'ont pas la même longueur ni le même sens. Pour le vérifier sans dessiner, il existe une formule qui vaut exactement 0 dans ce cas-là, jamais sinon : c'est le déterminant.", "titre": "Colinéarité : même direction ?"}, {"id": 12, "type": "methode", "content": "Pour u(x ; y) et v(x′ ; y′), le déterminant est det(u, v) = xy′ − x′y. On multiplie en croix, et on soustrait. Si le résultat est 0, les vecteurs sont colinéaires — et donc les droites qu'ils dirigent sont parallèles, ou les points qu'ils relient sont alignés. C'est le genre de chose qui tombe facilement au contrôle, alors autant s'entraîner dessus comme sur le reste.", "titre": "Calculer un déterminant"}, {"id": 13, "type": "exemple", "content": "A(1 ; 2) et B(4 ; 6).\n1) Coordonnées de $\\overrightarrow{AB}$ : (4 − 1 ; 6 − 2) = (3 ; 4).\n2) Norme : $\\sqrt{3^2+4^2} = \\sqrt{25} = 5$.\n3) Milieu de [AB] : ((1+4)/2 ; (2+6)/2) = (2,5 ; 4).", "titre": "Exemple résolu — coordonnées, norme, milieu"}, {"id": 14, "type": "exemple", "content": "A(−2 ; −1), B(2 ; −3), C(−4 ; 4), D(6 ; −1).\n1) $\\overrightarrow{AB}$ = (2−(−2) ; −3−(−1)) = (4 ; −2).\n2) $\\overrightarrow{CD}$ = (6−(−4) ; −1−4) = (10 ; −5).\n3) det($\\overrightarrow{AB}$, $\\overrightarrow{CD}$) = 4 × (−5) − 10 × (−2) = −20 + 20 = 0.\n4) Le déterminant est nul, donc $\\overrightarrow{AB}$ et $\\overrightarrow{CD}$ sont colinéaires : les droites (AB) et (CD) sont parallèles.", "titre": "Exemple résolu — colinéarité"}, {"id": 15, "type": "remarque", "content": "Lire les lettres dans le mauvais ordre : pour ABCD, c'est $\\overrightarrow{AB}$ = $\\overrightarrow{DC}$, pas $\\overrightarrow{AB}$ = $\\overrightarrow{CD}$.\nFaire départ moins arrivée au lieu d'arrivée moins départ : le signe change.\nOublier les parenthèses avec un négatif : 5 − (−2) = 7, pas 3.\nConfondre colinéaire et égal : colinéaire veut juste dire « même direction », pas « même trajet ».", "titre": "Pièges classiques"}, {"id": 16, "type": "remarque", "content": "La flèche se note toujours au-dessus des lettres : $\\overrightarrow{AB}$, jamais AB tout court — sanctionné si elle manque. Et le programme de ce chapitre, c'est tout en bloc : coordonnées, norme, milieu, ET colinéarité/déterminant. Pas juste l'égalité de deux vecteurs.", "titre": "Pour le contrôle"}]$coursJson4$, true);
